export function ActionBoard() {
  const { actions, updateAction } = useDemoData();
  const [notice, setNotice] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newOwner, setNewOwner] = useState('Maya Chen');
  const [newPriority, setNewPriority] = useState('Important');

  const handleAddAction = async () => {
    if (!newTitle.trim()) return;
    try {
      const { api } = await import('@/lib/api');
      await api.createAction({ incident_id: 'INC-1042', title: newTitle, owner: newOwner, priority: newPriority, due: 'TBD' });
      setNewTitle(''); setShowAddForm(false); setNotice('Action created successfully.');
      // Refresh
      const { useQueryClient } = await import('@tanstack/react-query');
    } catch (e) { setNotice('Failed to create action.'); }
  };

  return <AppShell><PageHeader eyebrow="Venue operations / follow-through" title="Corrective actions" description="The work after the incident. Add proof as you close the loop." action={<button data-testid="button-add-action" onClick={() => setShowAddForm(!showAddForm)} className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]"><Plus size={16} />Add action</button>} />{showAddForm && <div className="mb-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><p className="text-sm font-bold">New corrective action</p><div className="mt-4 grid gap-3 sm:grid-cols-3"><input value={newTitle} onChange={(e) => setNewTitle(e.target.value)} placeholder="Action title" className="rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none" /><input value={newOwner} onChange={(e) => setNewOwner(e.target.value)} placeholder="Owner" className="rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none" /><select value={newPriority} onChange={(e) => setNewPriority(e.target.value)} className="rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 py-2.5 text-sm outline-none"><option>Urgent</option><option>Important</option><option>Routine</option></select></div><div className="mt-4 flex gap-2"><button onClick={handleAddAction} className="rounded-xl bg-[hsl(var(--primary))] px-4 py-2 text-xs font-bold text-[hsl(var(--primary-foreground))]">Create</button><button onClick={() => setShowAddForm(false)} className="rounded-xl border border-[hsl(var(--border))] px-4 py-2 text-xs font-bold">Cancel</button></div></div>}{notice && <div className="mb-4 flex items-center justify-between rounded-xl bg-[hsl(var(--accent)/.16)] p-3 text-sm"><span>{notice}</span><button data-testid="button-dismiss-notice" onClick={() => setNotice('')}><X size={16} /></button></div>}<div className="mb-5 flex gap-2"><Pill tone="bad">{actions.filter((a) => a.status === 'Open').length} open</Pill><Pill tone="warn">{actions.filter((a) => a.status === 'In progress').length} in progress</Pill><Pill tone="good">{actions.filter((a) => a.status === 'Complete').length} complete</Pill></div><div className="grid gap-4 lg:grid-cols-3">{(['Open', 'In progress', 'Complete'] as const).map((status) => <div key={status} className="rounded-2xl bg-[hsl(var(--muted)/.55)] p-3"><div className="flex items-center justify-between px-2 py-2"><h2 className="text-xs font-bold uppercase tracking-wider">{status}</h2><span className="font-mono-ui text-xs text-[hsl(var(--muted-foreground))]">{actions.filter((a) => a.status === status).length}</span></div><div className="space-y-3">{actions.filter((a) => a.status === status).map((action) => <div key={action.id} data-testid={`card-action-${action.id}`} className="rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 shadow-sm"><div className="flex items-start justify-between gap-2"><Pill tone={toneFor(action.priority)}>{action.priority}</Pill><button data-testid={`button-action-menu-${action.id}`} onClick={() => { const newStatus = action.status === 'Complete' ? 'Open' : action.status === 'Open' ? 'In progress' : 'Open'; updateAction(action.id, { status: newStatus }); }} className="text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--primary))]" title={action.status === 'Complete' ? 'Move to Open' : action.status === 'Open' ? 'Move to In Progress' : 'Move to Open'}><SlidersHorizontal size={15} /></button></div><h3 className="mt-4 text-sm font-bold leading-5">{action.title}</h3><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{action.incident} · {action.owner}</p><div className="mt-4 flex items-center gap-2 border-t border-[hsl(var(--border))] pt-3 text-xs text-[hsl(var(--muted-foreground))]"><Paperclip size={13} />{action.proof}</div>{status !== 'Complete' && <div className="mt-3 flex gap-2"><button data-testid={`button-upload-proof-${action.id}`} onClick={() => updateAction(action.id, { proof: 'Proof uploaded just now', status: 'Complete' })} className="flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-[hsl(var(--border))] py-2 text-[11px] font-bold"><CloudUpload size={13} />Simulate proof</button><button data-testid={`button-complete-action-${action.id}`} onClick={() => updateAction(action.id, { status: 'Complete' })} className="rounded-lg bg-[hsl(var(--primary))] px-3 text-[11px] font-bold text-[hsl(var(--primary-foreground))]"><Check size={14} /></button></div>}</div>)}</div></div>)}</div></AppShell>;
}

export function EvidenceRoom() {
  const { evidence, updateEvidence } = useDemoData();
  const [selected, setSelected] = useState(evidence[0].id);
  const [uploaded, setUploaded] = useState(false);
  const item = evidence.find((e) => e.id === selected) || evidence[0];
  return <AppShell><PageHeader eyebrow="Venue operations / source record" title="Evidence room" description="Preserve what happened. Every item stays tied to its source and status." action={<><input id="file-upload-input" type="file" className="hidden" onChange={async (e) => { const file = e.target.files?.[0]; if (!file) return; try { const { api } = await import('@/lib/api'); const evidenceItem = evidence.find((ev) => ev.id === selected) || evidence[0]; const fullEvidence = await import('@/lib/api').then(m => m.api.getVenueEvidence('moonlight')); const fullItem = fullEvidence.evidence.find((ev: any) => ev.id.startsWith(evidenceItem?.id || '')); if (!fullItem) return; const urlData = await api.requestUploadURL(fullItem.id, file.name, file.type); await fetch(urlData.upload_url, { method: 'PUT', headers: { 'Content-Type': file.type }, body: file }); await api.confirmUpload(fullItem.id, urlData.object_key); setUploaded(true); updateEvidence(selected, { status: 'Pending review' }); } catch (err) { console.error('Upload failed:', err); } }} /><button data-testid="button-upload-evidence" onClick={() => document.getElementById('file-upload-input')?.click()} className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-3 text-sm font-bold text-[hsl(var(--primary-foreground))]"><Upload size={16} />Add evidence</button></>} />{uploaded && <div className="mb-4 rounded-xl bg-[hsl(161_31%_43%/.14)] p-3 text-sm text-[hsl(161_31%_36%)]">Simulated upload added. A reviewer still needs to verify the source.</div>}<div className="grid gap-4 lg:grid-cols-[.9fr_1.1fr]"><Panel className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] p-5"><h2 className="font-semibold">INC-1042 evidence checklist</h2><div className="mt-4 h-2 rounded-full bg-[hsl(var(--muted))]"><div className="h-full w-[67%] rounded-full bg-[hsl(var(--accent))]" /></div><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">4 of 6 source items complete</p></div><div>{evidence.map((entry) => <button key={entry.id} data-testid={`button-evidence-${entry.id}`} onClick={() => setSelected(entry.id)} className={`flex w-full items-start gap-3 border-b border-[hsl(var(--border))] p-4 text-left ${selected === entry.id ? 'bg-[hsl(var(--muted)/.62)]' : 'hover:bg-[hsl(var(--muted)/.35)]'}`}><span className={`mt-0.5 grid size-7 place-items-center rounded-lg ${entry.status === 'Verified' ? 'bg-[hsl(161_31%_43%/.14)] text-[hsl(161_31%_36%)]' : entry.status === 'Missing' ? 'bg-[hsl(var(--destructive)/.13)] text-[hsl(var(--destructive))]' : 'bg-[hsl(var(--accent)/.2)] text-[hsl(var(--primary))]'}`}>{entry.status === 'Verified' ? <CheckCircle2 size={15} /> : entry.status === 'Missing' ? <AlertTriangle size={15} /> : <Clock3 size={15} />}</span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{entry.label}</span><span className="mt-1 block text-xs text-[hsl(var(--muted-foreground))]">{entry.kind}</span></span><Pill tone={toneFor(entry.status)}>{entry.status}</Pill></button>)}</div></Panel><Panel className="p-6"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[hsl(var(--muted))] text-[hsl(var(--primary))]"><FileImage size={19} /></span><div><p className="font-mono-ui text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">{item.kind}</p><h2 className="mt-1 text-lg font-bold">{item.label}</h2></div></div><div className="mt-8 rounded-xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--muted)/.4)] p-8 text-center"><CloudUpload className="mx-auto text-[hsl(var(--muted-foreground))]" /><p className="mt-3 text-sm font-semibold">{item.status === 'Missing' ? 'No source attached yet' : 'Source preview unavailable in demo'}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Uploads are simulated and never leave this browser.</p><button data-testid="button-detail-upload" onClick={() => updateEvidence(item.id, { status: 'Pending review', updated: 'Uploaded just now' })} className="mt-5 rounded-lg border border-[hsl(var(--border))] px-3 py-2 text-xs font-bold">Simulate upload</button></div><dl className="mt-7 grid gap-5 border-t border-[hsl(var(--border))] pt-5 sm:grid-cols-2"><div><dt className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Status</dt><dd className="mt-2"><Pill tone={toneFor(item.status)}>{item.status}</Pill></dd></div><div><dt className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Last updated</dt><dd className="mt-2 text-sm">{item.updated}</dd></div><div className="sm:col-span-2"><dt className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Record note</dt><dd className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{item.detail}</dd></div></dl></Panel></div></AppShell>;
}

export function ScorePage() {
  const { scoreHistory } = useDemoData();
  return <AppShell><PageHeader eyebrow="Venue operations / measurable readiness" title="Savings Score" description="A deterministic view of documented risk readiness, not a prediction." action={<button data-testid="button-score-export" onClick={() => { window.open('/api/exports/venues/moonlight/score', '_blank'); }} className="inline-flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-4 py-3 text-sm font-bold"><Download size={16} />Export score</button>} /><div className="grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><Panel className="flex flex-col items-center justify-center p-7 text-center"><p className="font-mono-ui text-[10px] uppercase tracking-[.18em] text-[hsl(var(--muted-foreground))]">Current score</p><div className="relative mt-6 size-56"><svg className="size-full -rotate-90" viewBox="0 0 120 120"><circle cx="60" cy="60" r="51" fill="none" stroke="hsl(var(--muted))" strokeWidth="9" /><circle cx="60" cy="60" r="51" fill="none" stroke="hsl(var(--accent))" strokeWidth="9" strokeLinecap="round" strokeDasharray={`${58 * 3.2} 320`} /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span data-testid="text-score-value" className="font-display text-6xl">58</span><span className="text-xs text-[hsl(var(--muted-foreground))]">out of 100</span></div></div><div className="mt-4 flex items-center gap-2"><Pill tone="bad">−14 this week</Pill><span className="text-xs text-[hsl(var(--muted-foreground))]">High attention</span></div><p className="mt-5 max-w-xs text-xs leading-5 text-[hsl(var(--muted-foreground))]">Higher scores indicate stronger documented risk readiness.</p></Panel><Panel className="p-6"><div className="flex items-start justify-between"><div><h2 className="font-semibold">Score history</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Moonlight Club · trailing six months</p></div><Pill tone="bad">Trending down</Pill></div><div className="mt-8 h-[235px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={scoreHistory}><defs><linearGradient id="scoreFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="hsl(var(--accent))" stopOpacity={.45} /><stop offset="100%" stopColor="hsl(var(--accent))" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="hsl(var(--border))" vertical={false} /><XAxis dataKey="month" tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} axisLine={false} tickLine={false} /><YAxis domain={[40, 90]} tick={{ fill: 'hsl(var(--muted-foreground))', fontSize: 11 }} axisLine={false} tickLine={false} /><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid hsl(var(--border))', background: 'hsl(var(--card))', color: 'hsl(var(--foreground))' }} /><Area type="monotone" dataKey="score" stroke="hsl(var(--primary))" strokeWidth={3} fill="url(#scoreFill)" /></AreaChart></ResponsiveContainer></div></Panel></div><div className="mt-4 grid gap-4 lg:grid-cols-2"><Panel className="p-6"><h2 className="font-semibold">How the score is built</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">A transparent weighted formula that rewards consistent, documented operating practice.</p><div className="mt-6 space-y-4">{[['Evidence completeness', '30%', 67], ['Corrective action closure', '25%', 42], ['Response documentation', '25%', 82], ['Review cadence', '20%', 74]].map(([label, weight, value]) => <div key={String(label)}><div className="flex justify-between text-xs"><span>{label} <span className="text-[hsl(var(--muted-foreground))]">· {weight}</span></span><span className="font-mono-ui">{value}</span></div><div className="mt-2 h-1.5 rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${value}%` }} /></div></div>)}</div><p className="mt-6 border-t border-[hsl(var(--border))] pt-4 text-xs italic text-[hsl(var(--muted-foreground))]">This score is based on documented factors, not an AI opinion.</p></Panel><Panel className="p-6"><h2 className="font-semibold">What moves it next</h2><div className="mt-5 space-y-3">{['Confirm Camera 3 preservation', 'Collect the door lead statement', 'Close the wet-floor checkpoint'].map((item, i) => <div key={item} className="flex items-center gap-3 rounded-xl bg-[hsl(var(--muted)/.55)] p-4"><span className="font-mono-ui text-xs text-[hsl(var(--primary))]">+{[12, 8, 6][i]} pts</span><span className="text-sm font-semibold">{item}</span></div>)}</div><Link href="/venue/actions" data-testid="link-score-actions" className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-[hsl(var(--primary))]">Open action board <ArrowRight size={14} /></Link></Panel></div></AppShell>;
}

export function Copilot() {
  const defaultMsg = [{ from: 'guide', text: 'I can help you find the next documented step. Ask about incidents, evidence gaps, your Savings Score, or what actions to prioritize.' }];
  const [messages, setMessages] = useState<Array<{ from: string; text: string; citations?: Array<{ source: string; section?: string | null }>; cached?: boolean; guardrail?: boolean }>>(() => { try { const saved = sessionStorage.getItem('afterlight-chat'); return saved ? JSON.parse(saved) : defaultMsg; } catch { return defaultMsg; } });
  const updateMessages = (updater: (prev: typeof messages) => typeof messages) => { setMessages((prev) => { const next = updater(prev); try { sessionStorage.setItem('afterlight-chat', JSON.stringify(next)); } catch {} return next; }); };
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const send = async (event: FormEvent) => {
    event.preventDefault();
    if (!input.trim() || loading) return;
    const prompt = input;
    setInput('');
    updateMessages((m) => [...m, { from: 'you', text: prompt }]);
    setLoading(true);
    try {
      const { api } = await import('@/lib/api');
      const result = await api.chat(prompt);
      updateMessages((m) => [...m, {
        from: 'guide',
        text: result.answer,
        citations: result.citations,
        cached: result.is_cached,
        guardrail: result.guardrail_triggered,
      }]);
    } catch (e) {
      updateMessages((m) => [...m, { from: 'guide', text: 'Something went wrong. Try again.' }]);
    } finally {
      setLoading(false);
    }
  };
  return <AppShell><PageHeader eyebrow="Venue operations / cited guidance" title="AfterLight guide" description="A focused place to ask about your records. Answers stay grounded in your workspace data." /><div className="mx-auto grid max-w-5xl gap-4 lg:grid-cols-[1fr_.7fr]"><Panel className="flex min-h-[580px] flex-col"><div className="flex items-center gap-3 border-b border-[hsl(var(--border))] p-5"><span className="grid size-9 place-items-center rounded-xl bg-[hsl(var(--accent))] text-[hsl(var(--primary))]"><MessageSquare size={17} /></span><div><h2 className="text-sm font-bold">Cited workspace guide</h2><p className="text-xs text-[hsl(var(--muted-foreground))]">Grounded in your data · No autonomous decisions</p></div><Pill tone="good">Live</Pill></div><div className="flex-1 space-y-5 overflow-auto p-5">{messages.map((message, index) => <div key={`${message.from}-${index}`} className={`flex ${message.from === 'you' ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-6 ${message.from === 'you' ? 'rounded-br-sm bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'rounded-bl-sm bg-[hsl(var(--muted))]'}`}><p>{message.text}</p>{message.from === 'guide' && message.citations && message.citations.length > 0 && <div className="mt-3 space-y-1 border-t border-[hsl(var(--border))] pt-3">{message.citations.map((cite, ci) => { const link = cite.source?.includes('incident') ? `/venue/incidents/${cite.section?.match(/INC-\d+/)?.[0] || ''}` : cite.source?.includes('action') ? '/venue/actions' : cite.source?.includes('evidence') ? '/venue/evidence' : cite.source?.includes('score') ? '/venue/score' : '/venue/playbook'; return <Link key={ci} href={link} className="flex items-center gap-2 text-[10px] font-mono-ui text-[hsl(var(--primary))] hover:underline cursor-pointer"><FileText size={10} />{cite.source}{cite.section ? ` / ${cite.section}` : ''}</Link>; })}</div>}{message.from === 'guide' && message.cached && <span className="mt-2 inline-block rounded-full bg-[hsl(var(--accent)/.2)] px-2 py-0.5 text-[9px] font-mono-ui text-[hsl(var(--primary))]">cached</span>}{message.from === 'guide' && message.guardrail && <span className="mt-2 inline-block rounded-full bg-[hsl(var(--destructive)/.1)] px-2 py-0.5 text-[9px] font-mono-ui text-[hsl(var(--destructive))]">guardrail</span>}</div></div>)}{loading && <div className="flex justify-start"><div className="rounded-2xl rounded-bl-sm bg-[hsl(var(--muted))] px-4 py-3 text-sm"><span className="inline-flex gap-1"><span className="size-2 animate-bounce rounded-full bg-[hsl(var(--primary))]" /><span className="size-2 animate-bounce rounded-full bg-[hsl(var(--primary))] [animation-delay:0.1s]" /><span className="size-2 animate-bounce rounded-full bg-[hsl(var(--primary))] [animation-delay:0.2s]" /></span></div></div>}</div><form onSubmit={send} className="flex gap-2 border-t border-[hsl(var(--border))] p-4"><input data-testid="input-copilot-message" value={input} onChange={(e) => setInput(e.target.value)} placeholder="Ask about your record…" className="focus-ring min-w-0 flex-1 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-4 py-3 text-sm outline-none" disabled={loading} /><button data-testid="button-send-copilot" disabled={loading} className="grid size-11 place-items-center rounded-xl bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] disabled:opacity-50" aria-label="Send message"><Send size={16} /></button></form></Panel><div className="space-y-4"><Panel className="p-5"><p className="font-mono-ui text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Suggested questions</p><div className="mt-4 space-y-2">{['What is missing from INC-1042?', 'Why did my score change?', 'Which action is most urgent?', 'What does the entrance safety playbook say?', 'How many incidents this month?'].map((question) => <button key={question} data-testid={`button-suggestion-${question.slice(0, 8)}`} onClick={() => setInput(question)} className="flex w-full items-center justify-between rounded-xl border border-[hsl(var(--border))] p-3 text-left text-xs font-semibold hover:bg-[hsl(var(--muted))]">{question}<ArrowRight size={14} /></button>)}</div></Panel><div className="rounded-2xl border border-[hsl(var(--accent)/.5)] bg-[hsl(var(--accent)/.13)] p-5"><p className="text-sm font-bold">Human review required</p><p className="mt-2 text-xs leading-5 text-[hsl(var(--muted-foreground))]">The guide can point to sources and cite your records, but a person approves every action plan and risk conclusion.</p></div></div></div></AppShell>;
}

export function PlaybookViewer() {
  const [chunks, setChunks] = useState<Array<{ id: string; document_title: string; section_title: string; content: string }>>([]);
  const [loaded, setLoaded] = useState(false);
  const [expanded, setExpanded] = useState<string | null>(null);

  if (!loaded) {
    import('@/lib/api').then(({ api }) => api.getPlaybooks()).then((data) => { setChunks(data.chunks); setLoaded(true); }).catch(() => setLoaded(true));
  }

  // Group by document
  const documents = chunks.reduce((acc, chunk) => {
    if (!acc[chunk.document_title]) acc[chunk.document_title] = [];
    acc[chunk.document_title].push(chunk);
    return acc;
  }, {} as Record<string, typeof chunks>);

  return <AppShell><PageHeader eyebrow="Venue operations / reference" title="Playbook library" description="Approved operating procedures and response protocols. Referenced by the AfterLight guide." />{!loaded ? <p className="text-sm text-[hsl(var(--muted-foreground))]">Loading playbooks…</p> : Object.entries(documents).map(([title, sections]) => <div key={title} className="mb-4 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><div className="border-b border-[hsl(var(--border))] p-5"><h2 className="text-lg font-bold">{title}</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{sections.length} sections</p></div><div>{sections.map((section) => <div key={section.id} className="border-b border-[hsl(var(--border))] last:border-0"><button onClick={() => setExpanded(expanded === section.id ? null : section.id)} className="flex w-full items-center justify-between p-4 text-left hover:bg-[hsl(var(--muted)/.3)]"><span className="text-sm font-semibold">{section.section_title}</span><ArrowRight size={14} className={`transition-transform ${expanded === section.id ? 'rotate-90' : ''}`} /></button>{expanded === section.id && <div className="border-t border-[hsl(var(--border))] bg-[hsl(var(--muted)/.2)] p-5"><p className="text-sm leading-7 text-[hsl(var(--muted-foreground))]">{section.content}</p></div>}</div>)}</div></div>)}</AppShell>;
}

export function VenueGuard() {
  return <Restricted />;
}